#include <set>
#include <iostream>

struct ThresholdComp {
    int threshold;
    ThresholdComp(int t) : threshold(t) {}
    bool operator()(int a, int b) const {
        // Custom logic: sort based on distance from threshold
        return std::abs(a - threshold) < std::abs(b - threshold);
    }
};

int main() {
    // Initialize set with a stateful comparator
    std::set<int, ThresholdComp> s(ThresholdComp(50));

    s.insert(60); // Distance 10
    s.insert(45); // Distance 5 (closer to 50)

    // Output depends on the state (50) of the comparator
    for (int x : s) {
        std::cout << x << " "; // Output: 45 60 
    }
}
